class UserProfileSerializer(serializers.ModelSerializer):
    recent_transaction = serializers.SerializerMethodField()

    class Meta:
        model = User
        fields = ['id', 'username', 'email', 'recent_transaction']

    def get_recent_transaction(self, obj):
        tx_id = self.context['request'].query_params.get('preview_tx_id')
        if tx_id:
            tx = Transaction.objects.filter(id=tx_id, user=self.context['request'].user).first()
            if tx:
                return {'id': tx.id, 'amount': str(tx.amount), 'recipient': tx.recipient_name}
        return None
